-- 세트 345: Deployment 롤아웃 손연습: set image, rollout status, history, undo, pause, scale, strategy patch
-- 명세: docs/specs/spec_k8s_rollout_set.md. 정답·해설은 서버만 안다. 실습 문제의 grade_cmd 는 checks 의 조건을 && 로 이은 것과 같다.
INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (345, 1, 'rollout status 로 끝날 때까지 기다린 결과 저장하기', 'Deployment `ro-web`(복제본 3개, 이미지 `nginx:1.24`)이 떠 있습니다. 이미지를 `nginx:1.25` 로 바꾸고, **새 Pod 가 모두 준비될 때까지 기다린 뒤 그 결과 메시지를 `/tmp/status.txt` 에 저장**하세요. (컨테이너 이름은 `nginx` 예요.)', '`kubectl set image 종류/이름 컨테이너=이미지` 로 바꾸고, `kubectl rollout status 종류/이름` 은 끝날 때까지 기다리다가 마지막에 결과 한 줄을 보여 줘요. 그 출력을 `>` 로 파일에 담으세요.', 'kubectl set image deployment/ro-web nginx=nginx:1.25 -n $NS
kubectl rollout status deployment/ro-web -n $NS > /tmp/status.txt
cat /tmp/status.txt

# 마지막 줄: deployment "ro-web" successfully rolled out
# rollout status 는 끝날 때까지 붙잡고 기다린다. 막히면 계속 기다리므로 --timeout 으로 한도를 줄 수 있다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.24 --replicas=3 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.25\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( grep -Eq ''successfully rolled out'' /tmp/status.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.25 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.25\\" ]"]}, {"label": "Pod 3개가 모두 새 Pod 로 바뀌어 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "저장한 파일에 완료 메시지가 있다", "cmd": ["sh", "-c", "grep -Eq ''successfully rolled out'' /tmp/status.txt"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 2, '조건을 달아 안전하게 scale 하기', 'Deployment `ro-web` 의 복제본이 지금 **2개**입니다. 이 값이 **2개일 때만** 5개로 늘어나도록 안전 조건을 붙여 scale 하세요. 다른 사람이 먼저 바꿔 두었다면 실패하게 만드는 용도입니다.', '`kubectl scale --help` 에서 "현재 복제본 수가 이 값일 때만" 이라는 설명이 붙은 옵션을 찾아 보세요. `--replicas` 와 함께 써요.', 'kubectl scale deployment/ro-web --current-replicas=2 --replicas=5 -n $NS
kubectl get deployment ro-web -n $NS

# 현재 값이 2 가 아니면 ''precondition failed'' 로 거절된다
# 이 안전장치로 "내가 본 상태 그대로일 때만" 바꿀 수 있다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.25 --replicas=2 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"5\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"5-5-5\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "복제본 수가 5 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.replicas}'' 2>/dev/null)\\" = \\"5\\" ]"]}, {"label": "Pod 5개가 모두 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"5-5-5\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 3, '변경 사유를 버전마다 따로 남기기', 'Deployment `ro-web`(이미지 `nginx:1.24`)이 떠 있고, 아직 변경 사유가 없습니다. **지금 버전(REVISION 1)의 사유를 `initial 1.24` 로**, 이미지를 `nginx:1.25` 로 바꿔 생긴 **새 버전(REVISION 2)의 사유를 `upgrade 1.25` 로** 남겨서 `rollout history` 의 CHANGE-CAUSE 칸에 각각 보이게 하세요.', '사유는 Deployment 의 `kubernetes.io/change-cause` annotation 이 정해요. 사유를 쓰면 그 시점에 현재 버전에 붙으니, 쓰는 때(바꾸기 전과 후)를 생각해 보세요. 새 버전은 `rollout status` 로 생긴 것을 확인한 뒤에 적으면 안전해요.', 'kubectl annotate deployment/ro-web -n $NS kubernetes.io/change-cause=''initial 1.24'' --overwrite
kubectl set image deployment/ro-web nginx=nginx:1.25 -n $NS
kubectl rollout status deployment/ro-web -n $NS
kubectl annotate deployment/ro-web -n $NS kubernetes.io/change-cause=''upgrade 1.25'' --overwrite
kubectl rollout history deployment/ro-web -n $NS

# 1  initial 1.24
# 2  upgrade 1.25
# 사유는 "그 순간의 버전" 에 붙는다. 업데이트 전에는 옛 버전에, 후에는 새 버전에 적힌다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.24 --replicas=2 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( kubectl rollout history deployment/ro-web -n $NS 2>/dev/null | grep -Eq ''^1[[:space:]]+initial 1\\\\.24$'' ) && ( kubectl rollout history deployment/ro-web -n $NS 2>/dev/null | grep -Eq ''^2[[:space:]]+upgrade 1\\\\.25$'' ) && ( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.25\\" ] && ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"2-2-2\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "REVISION 1 의 CHANGE-CAUSE 가 initial 1.24 이다", "cmd": ["sh", "-c", "kubectl rollout history deployment/ro-web -n $NS 2>/dev/null | grep -Eq ''^1[[:space:]]+initial 1\\\\.24$''"]}, {"label": "REVISION 2 의 CHANGE-CAUSE 가 upgrade 1.25 이다", "cmd": ["sh", "-c", "kubectl rollout history deployment/ro-web -n $NS 2>/dev/null | grep -Eq ''^2[[:space:]]+upgrade 1\\\\.25$''"]}, {"label": "이미지가 nginx:1.25 이고 Pod 2개가 Ready 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.25\\" ] && ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"2-2-2\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 4, 'rollout history --revision 으로 옛 버전의 이미지 읽기', 'Deployment `ro-web` 은 `nginx:1.24` → `nginx:1.25` → `nginx:1.27-alpine` 순서로 두 번 업데이트됐습니다. **REVISION 2 가 쓰던 이미지**가 무엇이었는지 이력에서 읽어, 이미지 이름만(`이름:태그`) `/tmp/rev2.txt` 에 저장하세요. 지금 버전은 그대로 두세요.', '`kubectl rollout history 종류/이름 --revision=번호` 는 그 버전의 Pod 템플릿을 보여 줘요. 그중 `Image:` 줄이 필요해요. `grep` 과 `awk` 로 값만 골라낼 수 있어요.', 'kubectl rollout history deployment/ro-web -n $NS --revision=2
kubectl rollout history deployment/ro-web -n $NS --revision=2 | grep ''Image:'' | awk ''{print $2}'' > /tmp/rev2.txt
cat /tmp/rev2.txt   # nginx:1.25

# history 만 보는 읽기 작업이라 Deployment 는 바뀌지 않는다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.24 --replicas=1 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; kubectl set image deployment/ro-web nginx=nginx:1.25 -n $NS >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; kubectl set image deployment/ro-web nginx=nginx:1.27-alpine -n $NS >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(tr -d ''[:space:]'' < /tmp/rev2.txt 2>/dev/null)\\" = \\"nginx:1.25\\" ] ) && ( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.27-alpine\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 REVISION 2 의 이미지만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(tr -d ''[:space:]'' < /tmp/rev2.txt 2>/dev/null)\\" = \\"nginx:1.25\\" ]"]}, {"label": "지금 이미지는 그대로 nginx:1.27-alpine 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.27-alpine\\" ]"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 5, 'undo 로 되돌릴 REVISION 고르기', '업데이트를 REVISION **2** 로 되돌리고 싶습니다. 알맞은 옵션을 빈칸에 고르세요.', '`kubectl rollout undo --help` 의 옵션 목록에서 "되돌아갈 버전" 을 정하는 옵션을 찾아 보세요.', NULL, NULL, '[]', 'fill', '["--to-revision", "--revision", "--to", "--rev"]', NULL, '`kubectl rollout undo` 는 `--to-revision=번호` 로 되돌아갈 버전을 정합니다. 옵션이 없으면 바로 전 버전으로 가요. `--revision=번호` 는 `rollout history` 에서 한 버전의 내용을 볼 때 쓰는 옵션이고, `--to`, `--rev` 는 이 명령에 없는 옵션이라 오류가 납니다.', '[0]', 'kubectl rollout undo deployment/web {0}=2', NULL, NULL),
  (345, 6, 'maxSurge 1, maxUnavailable 0 이면 업데이트 중에는?', '복제본 4개인 Deployment 의 전략이 `maxSurge: 1`, `maxUnavailable: 0` 입니다. 이미지를 바꿔 롤링 업데이트가 진행되는 동안의 설명으로 알맞은 것은 무엇일까요?', '`maxSurge` 는 원하는 개수보다 **몇 개 더** 띄울 수 있는지, `maxUnavailable` 은 **몇 개까지 쓸 수 없어도** 되는지예요. 4 에 더하고 빼 보세요.', NULL, NULL, '[]', 'choice', '["옛 Pod 를 먼저 하나 내려 최대 4개를 유지하고, 사용 가능한 Pod 는 3개까지 줄어든다", "새 Pod 가 먼저 떠서 최대 5개까지 늘어나고, 사용 가능한 Pod 는 항상 4개 이상이다", "새 Pod 가 먼저 떠서 최대 5개까지 늘어나고, 사용 가능한 Pod 는 3개까지 줄어든다", "옛 Pod 를 먼저 하나 내려 최대 4개를 유지하고, 사용 가능한 Pod 는 항상 4개 이상이다"]', 1, '`maxSurge: 1` 은 원하는 4개에 1개를 더한 최대 5개까지 Pod 가 늘어날 수 있다는 뜻이고, `maxUnavailable: 0` 은 사용 가능한 Pod 가 4개 아래로 내려가면 안 된다는 뜻입니다. 그래서 새 Pod 가 Ready 가 된 뒤에야 옛 Pod 를 하나씩 내립니다. 옛 Pod 를 먼저 내리거나 사용 가능한 Pod 가 3개로 줄어드는 것은 `maxSurge: 0`, `maxUnavailable: 1` 인 전략의 모습이고, 이 값에서는 Pod 를 내릴 여유가 생기려면 새 Pod 가 먼저 떠야 해요.', NULL, NULL, NULL, NULL),
  (345, 7, 'kubectl patch 로 업데이트 속도 규칙 바꾸기', 'Deployment `ro-web`(복제본 4개)은 기본 업데이트 전략(`RollingUpdate`)을 쓰고 있습니다. **`kubectl patch`** 로 `maxSurge` 를 **0**, `maxUnavailable` 을 **1** 로 바꾸세요. (새 Pod 를 더 띄우지 않고, 옛 Pod 를 하나씩 내리며 교체하는 방식이에요.)', '`kubectl patch 종류/이름 -p ''JSON''` 으로 일부만 고쳐요. 경로는 `spec` 아래 `strategy` 아래 `rollingUpdate` 예요. 확인은 `kubectl get ... -o yaml` 로 해 보세요.', 'kubectl patch deployment ro-web -n $NS -p ''{"spec":{"strategy":{"rollingUpdate":{"maxSurge":0,"maxUnavailable":1}}}}''
kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.strategy}''

# patch 는 적은 필드만 바꾸고 나머지는 그대로 둔다
# 템플릿이 아닌 strategy 만 바뀌므로 Pod 가 다시 뜨지는 않는다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.25 --replicas=4 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.strategy.rollingUpdate.maxSurge}-{.spec.strategy.rollingUpdate.maxUnavailable}'' 2>/dev/null)\\" = \\"0-1\\" ] ) && ( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.strategy.type}'' 2>/dev/null)\\" = \\"RollingUpdate\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"4-4-4\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "maxSurge 가 0 이고 maxUnavailable 이 1 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.strategy.rollingUpdate.maxSurge}-{.spec.strategy.rollingUpdate.maxUnavailable}'' 2>/dev/null)\\" = \\"0-1\\" ]"]}, {"label": "전략 종류는 RollingUpdate 그대로이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.strategy.type}'' 2>/dev/null)\\" = \\"RollingUpdate\\" ]"]}, {"label": "Pod 4개가 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"4-4-4\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 8, 'pause 로 여러 변경을 모아 한 번에 배포하기', 'Deployment `ro-web`(복제본 3개, `nginx:1.24`)에 **이미지 `nginx:1.25` 와 환경변수 `APP_MODE=prod`** 두 가지를 바꿔야 합니다. 변경할 때마다 롤아웃이 두 번 돌지 않도록, 배포를 잠시 멈추고 **두 가지를 모두 바꾼 뒤 한 번만 롤아웃**되게 하세요. 끝났을 때 새 버전은 REVISION 2 하나여야 하고, 일시 중지는 풀려 있어야 합니다.', '`kubectl rollout pause 종류/이름` 으로 멈추면 바꿔도 새 Pod 가 뜨지 않고, `kubectl rollout resume 종류/이름` 으로 풀면 모은 변경이 한 번에 나가요. 환경변수는 `kubectl set env` 로 바꿀 수 있어요.', 'kubectl rollout pause deployment/ro-web -n $NS
kubectl set image deployment/ro-web nginx=nginx:1.25 -n $NS
kubectl set env deployment/ro-web APP_MODE=prod -n $NS
kubectl rollout resume deployment/ro-web -n $NS
kubectl rollout status deployment/ro-web -n $NS
kubectl rollout history deployment/ro-web -n $NS   # 1, 2 두 줄뿐

# 멈춘 동안에는 템플릿만 바뀌고 Pod 는 그대로다. resume 하면 한 번에 롤아웃된다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.24 --replicas=3 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.25\\" ] ) && ( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env[0].name}={.spec.template.spec.containers[0].env[0].value}'' 2>/dev/null)\\" = \\"APP_MODE=prod\\" ] ) && ( ( i=0; while [ $i -lt 10 ]; do if [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.metadata.annotations.deployment\\\\.kubernetes\\\\.io/revision}'' 2>/dev/null)\\" = \\"2\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.paused}'' 2>/dev/null)\\" != \\"true\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.25 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.25\\" ]"]}, {"label": "환경변수 APP_MODE 가 prod 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].env[0].name}={.spec.template.spec.containers[0].env[0].value}'' 2>/dev/null)\\" = \\"APP_MODE=prod\\" ]"]}, {"label": "REVISION 이 2 이다 (롤아웃이 한 번만 돌았다)", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 10 ]; do if [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.metadata.annotations.deployment\\\\.kubernetes\\\\.io/revision}'' 2>/dev/null)\\" = \\"2\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "일시 중지가 풀려 있다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.paused}'' 2>/dev/null)\\" != \\"true\\" ]"]}, {"label": "Pod 3개가 새 설정으로 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 9, '막힌 업데이트 중에도 서비스가 유지되는지 세어 보기', 'Deployment `ro-web`(복제본 3개)을 일부러 틀린 이미지 태그로 업데이트해 둬서 새 Pod 가 이미지를 받지 못하고 롤아웃이 **막혀** 있습니다. (전략은 `maxSurge 1`, `maxUnavailable 0` 이에요.) **지금 사용 가능한(available) 복제본 수**를 Deployment 의 상태에서 읽어 숫자만 `/tmp/avail.txt` 에 저장하세요. 고치지는 마세요.', '`kubectl get deployment 이름 -o jsonpath=''{.status.필드}''` 로 상태 값을 읽을 수 있어요. `kubectl get deployment -o yaml` 의 `status:` 아래에서 "사용 가능" 에 해당하는 필드를 찾아 보세요.', 'kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.availableReplicas}'' > /tmp/avail.txt
cat /tmp/avail.txt   # 3

# 새 Pod 는 ErrImagePull 로 못 뜨지만, maxUnavailable 0 이라 옛 Pod 3개는 지워지지 않고 서비스를 계속한다
# 이것이 롤링 업데이트가 "틀린 배포" 에서도 서비스를 지켜 주는 이유다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.25 --replicas=3 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; kubectl patch deployment ro-web -n $NS -p ''{\\"spec\\":{\\"strategy\\":{\\"rollingUpdate\\":{\\"maxSurge\\":1,\\"maxUnavailable\\":0}}}}'' >/dev/null; kubectl set image deployment/ro-web nginx=nginx:1.27-alpne -n $NS >/dev/null; i=0; while [ $i -lt 90 ]; do kubectl get pods -n $NS -l app=ro-web -o jsonpath=''{.items[*].status.containerStatuses[*].state.waiting.reason}'' 2>/dev/null | grep -Eq \\"ErrImagePull|ImagePullBackOff\\" && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( [ \\"$(tr -d ''[:space:]'' < /tmp/avail.txt 2>/dev/null)\\" = \\"3\\" ] ) && ( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.27-alpne\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "저장한 파일에 사용 가능한 복제본 수 3 만 들어 있다", "cmd": ["sh", "-c", "[ \\"$(tr -d ''[:space:]'' < /tmp/avail.txt 2>/dev/null)\\" = \\"3\\" ]"]}, {"label": "고치지 않고 막힌 상태 그대로이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.27-alpne\\" ]"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 10, 'progressDeadlineSeconds 로 막힌 업데이트를 실패로 표시하기', 'Deployment `ro-web`(복제본 2개)이 틀린 이미지 태그로 업데이트되어 롤아웃이 막혀 있습니다. 기본으로는 **600초**가 지나야 "진행 실패" 로 표시돼요. 이 한도(`progressDeadlineSeconds`)를 **20초**로 줄여서, 얼마 안 가 Deployment 의 `Progressing` 상태가 **실패(`ProgressDeadlineExceeded`)** 로 바뀌게 하세요. 이미지는 고치지 마세요.', '`progressDeadlineSeconds` 는 Deployment 의 `spec` 바로 아래 필드예요. `kubectl patch` 로 바꾸고, 결과는 `kubectl get deployment 이름 -o yaml` 의 `status.conditions` 에서 봐요. 몇 초 기다려야 할 수 있어요.', 'kubectl patch deployment ro-web -n $NS -p ''{"spec":{"progressDeadlineSeconds":20}}''
kubectl rollout status deployment/ro-web -n $NS --timeout=60s   # error: ... exceeded its progress deadline
kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.conditions[?(@.type=="Progressing")].reason}''   # ProgressDeadlineExceeded

# 한도가 지나도 Deployment 가 알아서 되돌리지는 않는다. "실패" 라고 표시해 줄 뿐이라 사람이나 CI 가 보고 undo 한다', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.25 --replicas=2 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; kubectl set image deployment/ro-web nginx=nginx:1.27-alpne -n $NS >/dev/null; i=0; while [ $i -lt 90 ]; do kubectl get pods -n $NS -l app=ro-web -o jsonpath=''{.items[*].status.containerStatuses[*].state.waiting.reason}'' 2>/dev/null | grep -Eq \\"ErrImagePull|ImagePullBackOff\\" && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.progressDeadlineSeconds}'' 2>/dev/null)\\" = \\"20\\" ] ) && ( ( i=0; while [ $i -lt 90 ]; do if [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.conditions[?(@.type==\\"Progressing\\")].reason}'' 2>/dev/null)\\" = \\"ProgressDeadlineExceeded\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.27-alpne\\" ] )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "progressDeadlineSeconds 가 20 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.progressDeadlineSeconds}'' 2>/dev/null)\\" = \\"20\\" ]"]}, {"label": "Progressing 상태의 사유가 ProgressDeadlineExceeded 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 90 ]; do if [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.conditions[?(@.type==\\"Progressing\\")].reason}'' 2>/dev/null)\\" = \\"ProgressDeadlineExceeded\\" ]; then exit 0; fi; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "이미지는 고치지 않은 그대로이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.27-alpne\\" ]"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 11, '막힌 업데이트를 두 단계 전 버전으로 되돌리기', 'Deployment `ro-web`(복제본 3개)이 `nginx:1.24` → `nginx:1.25` → (틀린 태그) 순서로 업데이트되다가 마지막 업데이트에서 막혔습니다. 바로 전 버전(`nginx:1.25`)이 아니라 **맨 처음 버전(`nginx:1.24`)으로** 되돌려서 Pod 3개가 모두 Ready 가 되게 하세요.', '먼저 `kubectl rollout history 종류/이름` 으로 맨 처음 번호를 확인하세요. 그 번호로 되돌아가는 옵션은 `kubectl rollout undo --help` 에 있어요.', 'kubectl rollout history deployment/ro-web -n $NS
kubectl rollout undo deployment/ro-web -n $NS --to-revision=1
kubectl rollout status deployment/ro-web -n $NS
kubectl get pods -n $NS -l app=ro-web

# 옵션 없이 undo 하면 바로 전 버전이고, --to-revision 은 번호로 고른다
# 되돌려도 번호는 줄지 않고 새 REVISION 으로 올라간다 (이전 번호는 이력에서 사라진다)', '["sh", "-c", "rm -f /tmp/*.txt; kubectl delete deployment ro-web -n $NS --ignore-not-found --wait=true --timeout=90s >/dev/null 2>&1; kubectl create deployment ro-web -n $NS --image=nginx:1.24 --replicas=3 >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; kubectl set image deployment/ro-web nginx=nginx:1.25 -n $NS >/dev/null; kubectl rollout status deployment/ro-web -n $NS --timeout=90s >/dev/null 2>&1; kubectl set image deployment/ro-web nginx=nginx:1.27-alpne -n $NS >/dev/null; i=0; while [ $i -lt 90 ]; do kubectl get pods -n $NS -l app=ro-web -o jsonpath=''{.items[*].status.containerStatuses[*].state.waiting.reason}'' 2>/dev/null | grep -Eq \\"ErrImagePull|ImagePullBackOff\\" && break; sleep 1; i=$((i+1)); done; true"]', '["sh", "-c", "( [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.24\\" ] ) && ( ( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 ) ) && ( ! kubectl get pods -n $NS -l app=ro-web -o jsonpath=''{.items[*].spec.containers[*].image}'' | grep -q alpne )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "이미지가 nginx:1.24 이다", "cmd": ["sh", "-c", "[ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.spec.template.spec.containers[0].image}'' 2>/dev/null)\\" = \\"nginx:1.24\\" ]"]}, {"label": "Pod 3개가 모두 새 Pod 로 바뀌어 Ready 이다", "cmd": ["sh", "-c", "( i=0; while [ $i -lt 40 ]; do [ \\"$(kubectl get deployment ro-web -n $NS -o jsonpath=''{.status.updatedReplicas}-{.status.readyReplicas}-{.status.replicas}'' 2>/dev/null)\\" = \\"3-3-3\\" ] && exit 0; sleep 1; i=$((i+1)); done; exit 1 )"]}, {"label": "틀린 이미지를 쓰는 Pod 가 남아 있지 않다", "cmd": ["sh", "-c", "! kubectl get pods -n $NS -l app=ro-web -o jsonpath=''{.items[*].spec.containers[*].image}'' | grep -q alpne"]}]', '[{"title": "디플로이먼트 (롤링 업데이트, 롤백, 일시 중지)", "url": "https://kubernetes.io/docs/concepts/workloads/controllers/deployment/"}, {"title": "kubectl rollout", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_rollout/"}, {"title": "kubectl set image", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_set/kubectl_set_image/"}, {"title": "kubectl scale", "url": "https://kubernetes.io/docs/reference/kubectl/generated/kubectl_scale/"}, {"title": "kubectl patch 로 오브젝트 갱신", "url": "https://kubernetes.io/docs/tasks/manage-kubernetes-objects/update-api-object-kubectl-patch/"}]'),
  (345, 12, '여러 변경을 모아 배포하는 순서', '이미지와 환경변수를 한 번에 바꾸되 롤아웃은 한 번만 돌게 하는 절차를 순서대로 놓아 보세요.', '먼저 멈추고, 바꿀 것을 다 바꾸고, 풀고, 끝날 때까지 기다리고, 마지막에 이력을 확인하는 순서예요.', NULL, NULL, '[]', 'order', '["`kubectl rollout resume` 으로 일시 중지를 풀어 모은 변경을 내보낸다", "`kubectl rollout history` 로 REVISION 이 한 번만 올랐는지 확인한다", "`kubectl rollout pause` 로 배포를 잠시 멈춘다", "`set image`, `set env` 로 바꿀 것을 모두 바꾼다", "`kubectl rollout status` 로 새 Pod 가 모두 준비될 때까지 기다린다"]', NULL, '먼저 `rollout pause` 로 멈춰 두면 `set image`, `set env` 를 여러 번 해도 Pod 가 바로 바뀌지 않고 템플릿만 쌓입니다. 다 바꿨으면 `rollout resume` 으로 풀어 한 번에 롤아웃하고, `rollout status` 로 끝났는지 기다린 뒤, `rollout history` 에서 REVISION 이 한 번만 올랐는지 확인해요. 멈추지 않고 바꾸면 변경마다 롤아웃이 따로 돌아 REVISION 이 여러 번 올라갑니다.', '[2, 3, 0, 4, 1]', NULL, NULL, NULL);
